#!/usr/bin/env bash

# NOTE: Initial file generated by Claude Sonnet 5.5.

# Usage: generate-config.sh ENV_FILE [TEMPLATE] [OUTPUT]
#   Produces conf/actual.yaml (default) from conf/template.yaml (default) using
#   values from ENV_FILE. Run at image build time, because the project reads
#   actual.yaml through Template Haskell during compilation.
#
# Variables read from ENV_FILE (or the environment):
#   required: MAILTRAP_API_SECRET, SENDER_ADDRESS, SENDER_NAME
#   optional: CRYPTOGRAPHY_SECRET (random if unset: set it to keep it stable
#             across rebuilds), DB_HOST (localhost), DB_PORT (5432),
#             DB_NAME (zocalo), DB_USER (postgres), DB_PASSWORD (empty)

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=load-env.sh
source "${SCRIPT_DIR}/load-env.sh"

ENV_FILE="${1:?usage: generate-config.sh ENV_FILE [TEMPLATE] [OUTPUT]}"
TEMPLATE="${2:-conf/template.yaml}"
OUTPUT="${3:-conf/actual.yaml}"

load_env_file "$ENV_FILE"

: "${MAILTRAP_API_SECRET:?MAILTRAP_API_SECRET must be set}"
: "${SENDER_ADDRESS:?SENDER_ADDRESS must be set}"
: "${SENDER_NAME:?SENDER_NAME must be set}"

if [ -z "${CRYPTOGRAPHY_SECRET:-}" ]; then
  CRYPTOGRAPHY_SECRET="$(head -c 32 /dev/urandom | base64)"
fi

cp "$TEMPLATE" "$OUTPUT"

# set_key KEY VALUE: replaces the value of a top-level-indented "KEY: ..." line,
# writing it as a double-quoted YAML string.
set_key() {
  local value="$2"
  value="${value//\\/\\\\}"   # YAML: escape backslashes
  value="${value//\"/\\\"}"   # YAML: escape double quotes
  value="$(printf '%s' "$value" | sed -e 's/[\\&|]/\\&/g')"  # sed replacement escaping
  sed -i -E "s|^([[:space:]]*${1}:).*|\1 \"${value}\"|" "$OUTPUT"
}

# set_int_key KEY VALUE: like set_key, but writes an unquoted YAML number.
set_int_key() {
  if ! [[ "$2" =~ ^[0-9]+$ ]]; then
    echo "generate-config.sh: ${1} must be a whole number, got '${2}'" >&2
    exit 1
  fi
  sed -i -E "s|^([[:space:]]*${1}:).*|\1 ${2}|" "$OUTPUT"
}


set_key     cryptography-secret "$CRYPTOGRAPHY_SECRET"
set_key     host                "${DB_HOST:-localhost}"
set_int_key db-port             "${DB_PORT:-5432}"
set_key     db-name             "${DB_NAME:-zocalo}"
set_key     username            "${DB_USER:-postgres}"
set_key     password            "${DB_PASSWORD:-}"
set_key     mailtrap-api-secret "$MAILTRAP_API_SECRET"
set_key     sender-address      "$SENDER_ADDRESS"
set_key     sender-name         "$SENDER_NAME"
